  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. Dentro de la Jauría: qué ven otros Miembros",
  "privacy.s12.body": "El artículo 3 describe el GodsGrid público. Dentro de la Jauría —el área solo para Miembros— otros Miembros conectados ven más: tu nombre de pila, tu número dogipcio, el nombre y la foto de tu perro, los atributos que rellenaste sobre tu perro, los viajes que registraste o anunciaste, tus valoraciones y comentarios, y lo que hayas escrito en tu perfil. No ven tu dirección de correo electrónico, tu dirección postal, tus datos de pago ni tus mensajes con cualquier otra persona. Cuando anuncias un viaje como abierto, la ruta, la fecha y tu perro se vuelven visibles para todos los Miembros para que puedan pedir unirse — eso es lo que significa anunciarlo. Un viaje que mantienes privado solo lo ves tú y las personas que ya van. Tú eliges cuál de las dos opciones es, y puedes cambiarlo en cualquier momento.",
  "privacy.s13.title": "13. Mensajes y Denuncias",
  "privacy.s13.body": "Los mensajes privados entre Miembros se almacenan en nuestra base de datos (Supabase) para que las conversaciones sobrevivan entre sesiones. Base legal: art. 6(1)(b) del RGPD — son parte de la membresía que pagaste. No los leemos de forma rutinaria y nunca los usamos para publicidad ni perfilado. Abrimos una conversación solo cuando se denuncia, cuando investigamos un abuso o incidente de seguridad concreto, o cuando la ley lo exige. Una denuncia guarda el motivo que elegiste, tu nota opcional y una referencia a lo que denunciaste — no una copia aparte de ello. El bloqueo se almacena como un par de identificadores de miembro. Si eliminas tu cuenta, tus mensajes se eliminan con ella; la copia en el hilo de la otra persona permanece, mostrada como proveniente de un miembro eliminado, porque esa conversación también es suya.",
  "terms.s12.title": "12. Contenido que publicas",
  "terms.s12.body": "Junto a tu HEROGLYPH puedes publicar contenido dentro de la Jauría: fotos de viajes, rutas y ubicaciones, descripciones de viajes, valoraciones, comentarios y preguntas, y lo que escribas en tu perfil. Cuando marcas un viaje como recorrido, otros Miembros ven tu nombre de pila y los perros que lo recorrieron contigo. Conservas la propiedad de todo lo que publicas. Al publicarlo, le otorgas a DOGYPT s.r.o. una licencia mundial, libre de regalías y no exclusiva para almacenar, mostrar y adaptar ese contenido con el fin de operar y promocionar el Servicio — por ejemplo, mostrar la foto de tu viaje en el mapa, en un listado de viajes o en una tarjeta para compartir. La licencia dura mientras el contenido esté en el Servicio; si eliminas el contenido o tu cuenta, termina, excepto en las copias de seguridad, que caducan en su ciclo normal. No vendemos tu contenido ni lo licenciamos a nadie más para su propio uso. Publica solo lo que tienes derecho a publicar — eso incluye fotos tomadas por otra persona y personas reconocibles en ellas.",
  "terms.s13.title": "13. Mensajes entre Miembros",
  "terms.s13.body": "Los Miembros pueden escribirse directamente. Los mensajes son privados entre los participantes — no los leemos de forma rutinaria y nunca los usamos para publicidad. Se almacenan en nuestros servidores para que la conversación siga ahí cuando vuelvas, y podemos leer una conversación en tres casos: cuando alguien la denuncia, cuando investigamos un abuso o incidente de seguridad concreto, o cuando la ley lo exige. Puedes bloquear a otro Miembro en cualquier momento; el bloqueo es inmediato y funciona en ambos sentidos. Trata los mensajes como cualquier conversación en línea — no envíes datos de pago, contraseñas ni documentos que no quieras que se almacenen.",
  "terms.s14.title": "14. Denuncias y Moderación",
  "terms.s14.body": "Los perfiles, los viajes y las conversaciones se pueden denunciar. Una denuncia nos llega y la lee una persona — hoy es el fundador, Matej Stacho. Nuestro objetivo es revisar cada denuncia en un plazo de 7 días. Según lo que encontremos, podemos no hacer nada, eliminar el contenido, advertir al Miembro, limitar lo que puede publicar o cerrar su cuenta. Si actuamos sobre tu contenido, te diremos por qué por correo electrónico, y puedes responder y disputarlo. También podemos eliminar contenido por iniciativa propia cuando infringe el artículo 7. El abuso deliberado o repetido —acoso, spam, viajes falsos, contenido que involucre a menores— termina la cuenta sin más advertencia.",
