  "pack.cal.life.tip.weight.body": "De todo lo que puedes hacer por un perro, una cosa tiene la evidencia más sólida sobre la longevidad: no dejarlo engordar. La diferencia entre un perro delgado y uno levemente obeso son años, no meses. Deberías poder notarle las costillas sin apretar.",
  "pack.cal.life.tip.move.title": "Movimiento en terreno real, no una vuelta a la manzana",
  "pack.cal.life.tip.move.body": "El terreno irregular mantiene activas las articulaciones, los músculos y la mente. Cada viaje que registras se convierte en una semana oscura en esta cuadrícula — y las semanas oscuras son lo único que realmente puedes influir.",
  "pack.cal.life.tip.food.title": "Comida que el perro reconoce como comida",
  "pack.cal.life.tip.food.body": "Cuantos menos pasos haya entre el ingrediente crudo y el plato, menos cosas pueden salir mal en el camino. El pienso no es un pecado, pero tampoco es una dieta — es un atajo.",
  "pack.cal.life.tip.chem.title": "Química solo cuando realmente se necesita",
  "pack.cal.life.tip.chem.body": "Los antiparasitarios todo el año, la anestesia por comodidad y los antibióticos «por si acaso» son decisiones, no rutina. Pregúntate en cada caso: ¿qué pasa si no lo doy? Donde la respuesta sea «nada», no lo des.",
  "pack.cal.life.tip.stress.title": "El descanso cuenta tanto como el movimiento",
  "pack.cal.life.tip.stress.body": "Un perro que siempre está en alerta quema el cuerpo por dentro. Dormir sin interrupciones, un día predecible y calma después del esfuerzo no son pereza — son las horas en que el cuerpo se repara.",
  "pack.cal.life.tip.protocol.title": "Un protocolo en vez de una carrera de pánico al veterinario",
  "pack.cal.life.tip.protocol.body": "La desparasitación, la coprología y los análisis de sangre tienen sus propias ventanas en el calendario. Un perro al que le revisas la sangre dos veces al año no se está tratando — se le está adelantando.",
  "pack.cal.life.tip.joints.title": "Las articulaciones se tratan ANTES de que empiecen a doler",
  "pack.cal.life.tip.joints.body": "Tu perro ya está en la franja senior. La cura para las articulaciones tiene su ventana en el calendario desde noviembre — no porque cojee, sino para que nunca tenga que hacerlo.",
