  "pack.hero.popLevelTitle": "{name} · nivel {index} de 22",
  "pack.hero.popLevel1": "Tu nivel de devoción sube con las buenas acciones hechas por la raza canina — paseos, cuidados, una mano tendida a un perro en apuros.",
  "pack.hero.popLevel2": "La escalera tiene 22 escalones, iguales para todos, y ninguno se puede comprar. El conteo empieza cuando DOGYPT pase a la app móvil.",
  "pack.hero.popLevelStamp": "Empieza a contar con la app",
  "pack.hero.popBonesEyebrow": "Moneda",
  "pack.hero.popBones1": "Los BONES son la moneda de DOGYPT. Hoy los ganas trayendo a alguien más — un amigo te da +20 🦴, y cuando ese amigo trae a otro, +10 🦴 más. Los ves aquí mismo, en esta pastilla.",
  "pack.hero.popBones2": "En qué los vas a gastar se está construyendo — merchandising, recaudaciones para refugios, créditos de IA. Nada de lo que acumules ahora se pierde.",
  "pack.hero.popBonesCta": "Invitar a un amigo",
