  "pack.hero.popDevotion1": "La Devoción (☥) mide lo que realmente le das a tu perro — presencia, paseos, rituales diarios.",
  "pack.hero.popDevotion2": "Podrás acumularla cuando tengas la app a mano todos los días. Hasta entonces sería un medidor que no mide nada.",
  "pack.hero.popDevotionStamp": "Se desbloquea con la app · 2027",
  "pack.heroBadge.more": "Más sobre la historia →",
  "pack.heroBadge.trips": "{n} viajes",
  "pack.heroBadge.kickerMilestone": "Hito alcanzado",
  "pack.heroBadge.kickerEarned": "Insignia de héroe",
  "pack.heroBadge.kickerLocked": "{n} viajes más para desbloquear",
  "pack.heroBadge.hachiko.story": "Nueve años, nueve meses, quince días. Así de largo esperó el akita Hachikō en la estación de Shibuya a un hombre que nunca volvió. El profesor Hidesaburō Ueno lo adoptó en 1924 y lo acompañaba a la estación cada mañana, recogiéndolo allí cada tarde — un ritual que terminó el 21 de mayo de 1925, cuando el profesor murió en mitad de una clase. Hachikō no lo sabía. Fue a la estación esa tarde, y la siguiente, y un año después, y nueve años más tarde. No esperaba por una orden ni por una recompensa — esperaba porque la lealtad de un perro no funciona con lógica, funciona con vínculo. Japón le levantó una estatua mientras todavía estaba vivo. Hachikō no es simplemente un perro. Es una liturgia de lealtad, oficiada en el andén de una estación.",
  "pack.heroBadge.barry.story": "En el Gran Paso de San Bernardo, donde el hielo no perdona nada y la niebla roba el camino, sirvió un San Bernardo llamado Barry. Durante doce años caminó por donde otros temían poner un pie — hacia ventiscas a 2.500 metros, buscando viajeros perdidos antes de que la nieve pudiera llevárselos. No estaba entrenado para una orden. Su vocación estaba escrita bajo su pelaje. Salvó a más de cuarenta personas. La leyenda dice que murió a manos del cuadragésimo primero al que intentó rescatar; la verdad es más modesta — vivió sus últimos días en paz en Berna. DOGYPT lo honra no por el mito del martirio, sino por lo real: un perro que elegía caminar hacia la tormenta en lugar de quedarse donde estaba calientito.",
  "pack.heroBadge.togo.story": "Mientras el mundo se inclinaba ante Balto, el verdadero héroe llevaba tiempo dormitando en una vitrina de museo en Alaska. Togo, un husky siberiano de doce años hecho de cicatrices, guio al equipo de Leonhard Seppala por el tramo más largo y mortal de la carrera del suero — más de 260 millas de hielo, oscuridad y viento. Balto se llevó la gloria por las últimas 55 millas, la estatua en Central Park y los titulares. Togo se llevó el Norton Sound — el estrecho helado que empezó a romperse bajo sus patas, y que cruzó de todos modos, haciendo nadar a su equipo entre las grietas hasta la seguridad. DOGYPT no se arrodilla ante la fama fabricada para las cámaras — se arrodilla ante el perro que hizo el trabajo cuando nadie miraba.",
  "pack.heroBadge.hekthor.story": "Nadie lo quería. Siete cachorros en una caja, un hombre que no tenía planeado tener un perro — y aun así la chispa saltó hacia él. Así empezó Hekthor en 2017: una cosa negra y peluda nacida de la necesidad, que elegió a su humano antes de que el humano pudiera elegirlo a él. De aquel accidente nació un camino — literalmente. Cuarenta y dos días por Eslovaquia, kilómetro a kilómetro, a través de cadenas montañosas y valles. Del camino nació un libro. Del libro nació DOGYPT. Hekthor no es una mascota ni un logotipo — es el perro cero, la prueba de que una sola vida rescatada puede poner en marcha todo un movimiento. Sus cuarenta y dos días son el patrón del camino que recorre cada dogipcio: no hacia el rendimiento, sino hacia la conexión.",
  "pack.heroBadge.bothie.story": "Era un perro callejero cualquiera — un Jack Russell terrier de pelo largo que Ranulph y Ginny Fiennes encontraron en 1977. Dos años después estaba en la cubierta de un barco rumbo a una expedición que el mundo nunca había visto: Transglobe, el primer viaje alrededor de la Tierra siguiendo su meridiano, por ambos polos, enteramente por la superficie. Se saltó África — demasiado calor para un perro — pero cuando la expedición llegó al hielo, Bothie estaba allí. Nueve meses en la Antártida, y el 10 de abril de 1982 se plantó en el Polo Norte. El único perro de la historia que estuvo en ambos extremos del mundo. DOGYPT lo recuerda no porque sobrevivió a los polos, sino porque demostró que la lealtad y la curiosidad van más lejos que la mayoría de los planes humanos.",
  "pack.heroBadge.laika.story": "Antes que cualquier humano, voló ella. El 3 de noviembre de 1957 dejó las calles de Moscú, y días después también el cielo — en la cabina del Sputnik 2, construida en menos de un mes, sin ningún plan de regreso. Laika, una perra callejera que apenas pesaba cinco kilos, se convirtió en la primera criatura en órbita. La propaganda soviética hablaba de un vuelo tranquilo. La verdad — que murió en la cuarta órbita, cuando la cabina se calentó a cuarenta grados — no salió a la luz hasta 2002, después de 45 años de silencio. Por eso es una heroína de DOGYPT: no porque ganó, sino porque llegó a despegar. En 2008 Moscú le dedicó un monumento: una pata trepando hasta la punta de un cohete.",
  "pack.heroBadge.bobbie.story": "En agosto de 1923, Bobbie, un cruce de collie y pastor, se separó de la familia Brazier en una gasolinera de Indiana — a 4.100 kilómetros de casa. La familia lo buscó, pegó carteles y finalmente volvió a casa con las manos vacías. Bobbie no se rindió. Durante seis meses caminó solo a través de una América congelada — cruzando ríos a nado, atravesando la Divisoria Continental en pleno invierno, alimentado por gente que lo veía en campamentos a lo largo del camino. En febrero de 1924 entró en el restaurante de su familia en Silverton como si solo hubiera salido un momento. Esta no es una historia sobre la suerte. Es la prueba de que el camino a casa se puede recorrer incluso cuando nadie cree que sea posible — paso a paso, sin mapa, con la lealtad como brújula.",
  "pack.heroBadge.seaman.story": "Mientras la mayoría de los hombres del Corps of Discovery pedían un sueldo, Seaman solo pedía un lugar junto al fuego. Meriwether Lewis lo compró en Pittsburgh en 1803 por veinte dólares — medio sueldo mensual de capitán por un solo terranova. Mereció la pena. Tres años, a través de un continente, por el Missouri, sobre las Rocosas y hasta el Pacífico — y Seaman fue el único animal que hizo todo el viaje. Cazaba, vigilaba de noche contra los osos, una vez espantó a un bisonte del campamento. Cuando un castor le atravesó la arteria de un mordisco, Clark lo cosió él mismo. Cuando lo robaron, Lewis envió a tres hombres a traerlo de vuelta — no se abandona a un perro. Los diarios de la expedición lo mencionan por su nombre más veces que a la mayoría de los soldados.",
  "pack.heroBadge.savannah.story": "Savannah no es una leyenda inventada para causar efecto — es una perra que de verdad dio la vuelta al planeta a pie. Tom Turcich la sacó de una cuneta junto a una carretera de Texas cuando era una cachorra de cuatro meses. Cuatro meses antes, él había emprendido un viaje a pie alrededor del mundo; Savannah se unió a él, y desde ese día nunca dio un paso a su lado que no condujera a la meta. Siete años, seis continentes, decenas de países, cientos de miles de kilómetros — bajo lluvia, con calor, sobre los Andes, por la arena. Sin quejarse, con la cola arriba. Se convirtió en la primera y, hasta ahora, única perra en dar la vuelta al mundo a pie. En 2024, a los nueve años, murió en casa — después de un viaje que ningún otro perro ha hecho jamás. Savannah = 1000 viajes no es una metáfora. Para ella sería quedarse corto.",
