  "pack.nature.ans.no": "No",
  "pack.network.ads.body": "La publicidad de pago es una forma muy poco eficiente de encontrar nuevos amantes de los perros — y una manera de tirarle nuestro dinero a las grandes corporaciones. Funciona mucho mejor recompensar directamente a los miembros del movimiento por su actividad. Hay un truco: <strong style=\"font-weight:600\">solo funciona de verdad si sales y le hablas de nosotros a la gente de tu alrededor</strong> :)",
