  "pack.network.groupTheirBrings": "los que trajeron",
  "pack.network.inLine": "En tu línea",
  "pack.network.info.bones.body": "BONES es la moneda interna de DOGYPT — un nombre juguetón para algo real. Un perro paga en huesos; nosotros también. Los <b>ganas</b> trayendo amantes de los perros a la jauría y haciendo avanzar el movimiento, y los <b>gastas</b> dentro de DOGYPT: apoyando recaudaciones para refugios, consiguiendo merchandising, y más adelante pagando a otros dogipcios por lo que crean. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "¿Qué son los BONES?",
  "pack.network.info.why.body": "Un movimiento de este tamaño no se puede comprar — ningún presupuesto llega a un desconocido como un dogipcio llega a un amigo. Por eso la jauría pone la recompensa donde está el alcance: en ti. Cuando alguien se une a través de tu enlace, obtienes <b>{l1} BONES</b>; cuando esa persona trae a alguien más, obtienes <b>{l2}</b> más. Cada dogipcio que difunde la palabra no es un vendedor — es un misionero, y honramos ese trabajo.",
  "pack.network.info.why.cap": "Por qué te lo pedimos",
  "pack.network.intro": "Un movimiento solo crece cuando sus miembros llevan el mensaje y traen a gente nueva. Por eso te lo pedimos directamente: <strong style=\"color:#2a1608;font-weight:600\">invita a los amantes de los perros que conoces</strong>. Aquí está exactamente cómo funciona.",
